<template><view class="page"><view class="search-card"><text class="title">报手机号，快速核销</text><text class="sub">输入完整手机号或后四位，再当面核对购卡姓名</text><u-input v-model="mobile" type="number" maxlength="11" border="surround" placeholder="完整手机号或后四位" prefixIcon="phone"/><u-input v-model="name" border="surround" placeholder="多人命中时填写姓名（可选）"/><u-button type="primary" text="查询可用会员卡" :loading="loading" @click="search"/></view><view v-if="searched&&!candidates.length" class="empty"><u-empty text="没有找到可核销会员卡" mode="search"/></view><view v-for="candidate in candidates" :key="candidate.member_id" class="candidate"><view class="candidate-head"><view><text>请口头核对姓名</text><strong>{{candidate.holder_name}}</strong><small>{{candidate.mobile_masked}}</small></view><u-tag :text="`可用 ${candidate.available_card_count} 张`" :type="candidate.available_card_count?'success':'info'" plain/></view><view v-for="card in candidate.cards" :key="card.card_id" class="card" :class="{disabled:!card.available}"><view class="card-main"><strong>{{card.product_name}}</strong><text>{{card.item_name}} · {{card.validity_text}}</text><text>{{card.usage_mode==='unlimited'?'不限次':`剩余 ${card.remaining_times} 次`}}</text></view><u-button type="primary" size="small" :disabled="!card.available" :text="card.recommended?'核销 1 次':'核销'" @click="openConfirm(candidate,card)"/></view></view><u-popup :show="confirmVisible" mode="bottom" :safe-area-inset-bottom="true" border-radius="28rpx" @close="confirmVisible=false"><view v-if="selected" class="confirm-sheet"><view class="sheet-head"><text>确认核销 1 次</text><u-icon name="close" @click="confirmVisible=false"/></view><view class="verify"><text>请让客户说出购卡姓名</text><strong>{{selected.candidate.holder_name}}</strong><small>{{selected.candidate.mobile_masked}} · {{selected.card.product_name}}</small></view><view class="check" @click="confirmed=!confirmed"><u-checkbox :checked="confirmed" @change="confirmed=$event"/><text>我已当面核对手机号与姓名，信息一致</text></view><u-textarea v-model="remark" height="100rpx" placeholder="本次服务说明（选填）"/><view class="actions"><u-button text="取消" @click="confirmVisible=false"/><u-button type="primary" text="确认核销" :disabled="!confirmed" :loading="redeeming" @click="redeem"/></view></view></u-popup></view></template>
<script setup lang="ts">import{ref}from'vue';import{memberCardRequestId,redeemMemberCard,searchMemberCards}from'../../api';const mobile=ref(''),name=ref(''),loading=ref(false),searched=ref(false),candidates=ref<any[]>([]),confirmVisible=ref(false),selected=ref<any>(null),confirmed=ref(false),remark=ref(''),redeeming=ref(false);const search=async()=>{if(!/^\d{4}$|^1\d{10}$/.test(mobile.value))return uni.showToast({title:'请输入完整手机号或后四位',icon:'none'});loading.value=true;try{candidates.value=((await searchMemberCards({mobile_keyword:mobile.value,name:name.value}))as any)?.data?.candidates||[];searched.value=true}finally{loading.value=false}};const openConfirm=(candidate:any,card:any)=>{selected.value={candidate,card};confirmed.value=false;remark.value='';confirmVisible.value=true};const redeem=async()=>{if(!confirmed.value)return;const modal=await uni.showModal({title:'核销确认',content:'确认贴膜服务已经完成？核销后将扣减 1 次并记录当前操作人。',confirmText:'确认核销'});if(!modal.confirm)return;redeeming.value=true;try{const r:any=(await redeemMemberCard(selected.value.card.card_id,{request_id:memberCardRequestId('redeem'),card_item_id:selected.value.card.item_id,verification_confirmed:1,remark:remark.value}))?.data;uni.showToast({title:r?.message||'核销成功',icon:'success'});confirmVisible.value=false;await search()}finally{redeeming.value=false}}</script>
<style scoped>.page{min-height:100vh;padding:24rpx;background:#f3f4f6;box-sizing:border-box}.search-card{display:flex;padding:28rpx;border:1rpx solid #e5eaf1;border-radius:20rpx;background:#fff;flex-direction:column;gap:18rpx}.title{font-size:35rpx;font-weight:750}.sub{margin-top:-10rpx;color:#64748b;font-size:22rpx}.candidate{margin-top:20rpx;border:1rpx solid #e5eaf1;border-radius:18rpx;background:#fff;overflow:hidden}.candidate-head,.card,.sheet-head,.actions,.check{display:flex;align-items:center;justify-content:space-between;gap:18rpx}.candidate-head{padding:23rpx;background:#f8fafc}.candidate-head>view,.card-main,.verify{display:flex;flex-direction:column;gap:6rpx}.candidate-head text,.candidate-head small,.card-main text,.verify text,.verify small{color:#64748b;font-size:21rpx}.candidate-head strong{font-size:31rpx}.card{padding:24rpx;border-top:1rpx solid #eef2f7}.card.disabled{opacity:.5;background:#f8fafc}.card-main{flex:1}.empty{padding-top:100rpx}.confirm-sheet{padding:30rpx 26rpx}.sheet-head{font-size:32rpx;font-weight:750}.verify{margin:24rpx 0;padding:24rpx;background:#eff6ff;border-left:5rpx solid #3b6ef5}.verify strong{font-size:38rpx}.check{justify-content:flex-start;margin-bottom:22rpx}.actions{margin-top:24rpx}.actions>*{flex:1}</style>
